package chat
import("context";"crypto/sha256";"encoding/hex";"github.com/madkoding/kitties/internal/approvals";"github.com/madkoding/kitties/internal/connector";"github.com/madkoding/kitties/internal/kitty")
func(s *Service)lexopenPrepareMetadataApproval(ap *approvals.Approval,approve bool)(func(),error){
 if !approve{lock:=s.lockFor(ap.Chat);lock.Lock();return lock.Unlock,nil};if !ap.MetadataStageReady||ap.FileStageReady||!lexopenMetadataStageArgs(ap.Connector,ap.Action,lexopenMetadataTarget(ap.Args)){return nil,ErrStagedMetadataInvalid};lock:=s.lockFor(ap.Chat);lock.Lock();fail:=func(e error)(func(),error){lock.Unlock();return nil,e};sess,e:=s.Get(ap.Chat);if e!=nil||len(sess.Members)!=1||sess.Members[0]!=ap.Kitty{return fail(ErrStagedMetadataInvalid)};s.mu.RLock();busy:=sess.Working()||s.tasks[ap.Chat]!=nil;s.mu.RUnlock();if busy{return fail(ErrBusy)};k,e:=s.fleet.Get(ap.Kitty);if e!=nil||!k.Desktop||k.Status!=kitty.StatusRunning||s.lexopenPreflightCloudFile(k,action{kind:"connector",name:ap.Connector,args:ap.Args})!=nil{return fail(ErrStagedMetadataInvalid)};return lock.Unlock,nil
}
func lexopenMetadataTarget(args map[string]any)map[string]any{target:=map[string]any{};for key,value:=range args{if key!="action"{target[key]=value}};return target}
func(s *Service)lexopenDecideMetadata(ctx context.Context,ap *approvals.Approval,approve bool,reason string,always bool)(*approvals.Approval,error){
 if always{return nil,ErrStagedMetadataInvalid};unlock,e:=s.lexopenPrepareMetadataApproval(ap,approve);if e!=nil{return nil,e};defer unlock();ap,e=s.approvals.Decide(ap.ID,approve,reason,false);if e!=nil{return nil,e};turn:=Turn{At:s.now(),From:"approval",MetadataRequestID:ap.RequestID};if approve{k,_:=s.fleet.Get(ap.Kitty);if k==nil{return nil,ErrStagedMetadataUnavailable};res:=s.fleet.Connectors().Call(connector.LexOpenMetadataStageContext(ctx),connector.Call{Name:ap.Connector,Args:ap.Args},k.Connectors);var receipt *approvals.MetadataReceipt;if res.Err==""&&res.Name==ap.Connector&&res.Kind==ap.Kind&&res.File==nil&&res.Artifact==""&&res.StructuredReceipt==nil&&!res.OutputTruncated&&connector.LexOpenValidateMetadataTargetResult(ap.Kind,ap.Action,res.Output,lexopenMetadataTarget(ap.Args)){sum:=sha256.Sum256([]byte(res.Output));receipt=&approvals.MetadataReceipt{State:"metadata_ready",RequestID:ap.RequestID,ChatID:ap.Chat,Kitty:ap.Kitty,Connector:ap.Connector,Kind:ap.Kind,Action:ap.Action,ApprovalID:ap.ID,Target:lexopenMetadataTarget(ap.Args),SHA256:hex.EncodeToString(sum[:]),Bytes:len([]byte(res.Output))}}else{res.Output="";res.Err="The selected metadata response is unavailable.";res.File=nil;res.Artifact="";res.StructuredReceipt=nil};if e=s.approvals.DoneMetadataAction(ap.ID,res.Output,res.Err,receipt);e!=nil{return nil,ErrStagedMetadataUnavailable};ap.Result,ap.Error,ap.MetadataReceipt=res.Output,res.Err,receipt;turn.Calls=[]connector.Result{res};turn.Text="Consulta aprobada: respuesta parcial de metadatos.";if receipt!=nil {if text,ok:=lexopenReadableFileApproval(ap,res);ok{turn.Text=text}};if res.Err!=""{turn.Text="La consulta aprobada no produjo metadatos verificados."}}else{turn.Text="Consulta de metadatos rechazada."};if s.lexopenAppendMetadataTurn(ap.Chat,turn)!=nil{return nil,ErrStagedMetadataUnavailable};return ap,nil
}

func(s *Service)lexopenAppendMetadataTurn(id string,turn Turn)error{s.mu.Lock();defer s.mu.Unlock();sess,ok:=s.sessions[id];if !ok{return ErrStagedMetadataUnavailable};candidate:=*sess;candidate.Turns=append(append([]Turn(nil),sess.Turns...),turn);candidate.UpdatedAt=s.now();committed,e:=s.saveAsync(&candidate);if committed{s.sessions[id]=&candidate};if e!=nil{return ErrStagedMetadataUnavailable};s.emitLocked(Event{Type:"turn",Session:id,Index:len(candidate.Turns)-1,Turn:&candidate.Turns[len(candidate.Turns)-1]});return nil}
func lexopenHasMetadataTurn(sess *Session,ap *approvals.Approval)bool{for _,t:=range sess.Turns{if t.From=="approval"&&t.MetadataRequestID==ap.RequestID&&len(t.Calls)==1&&t.Calls[0].Name==ap.Connector&&t.Calls[0].Kind==ap.Kind&&t.Calls[0].Output==ap.Result&&t.Calls[0].Err==""{return true}};return false}
